import unittest
from candidate import sort_even

class TestSortEven(unittest.TestCase):
    def test_sort_even_empty_list(self):
        self.assertEqual(sort_even([]), [])

    def test_sort_even_single_even_value(self):
        self.assertEqual(sort_even([2]), [2])

    def test_sort_even_single_odd_value(self):
        self.assertEqual(sort_even([1]), [1])

    def test_sort_even_even_values(self):
        self.assertEqual(sort_even([2, 4, 6]), [2, 4, 6])

    def test_sort_even_odd_values(self):
        self.assertEqual(sort_even([1, 3, 5]), [1, 3, 5])

    def test_sort_even_mixed_values(self):
        self.assertEqual(sort_even([5, 2, 3, 4, 1]), [3, 5, 2, 4, 1])

    def test_sort_even_duplicates(self):
        self.assertEqual(sort_even([2, 2, 4, 6]), [2, 2, 4, 6])

    def test_sort_even_reverse_order(self):
        self.assertEqual(sort_even([6, 4, 2]), [2, 4, 6])

    def test_sort_even_negative_values(self):
        self.assertEqual(sort_even([-2, -4, -6]), [-6, -4, -2])

    def test_sort_even_none_value(self):
        self.assertEqual(sort_even(None), None)

    def test_sort_even_type_error(self):
        with self.assertRaises(TypeError):
            sort_even(123)

if __name__ == '__main__':
    unittest.main()
